#include "derelict/SalvageTransactionRuntime.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
namespace elysium::derelict {bool SalvageRuntime::publish(SalvageItem i){if(!i.stableId||!i.contentId||!i.count||!i.unitMass||!i.unitVolume||items_.contains(i.stableId))return false;i.remainingCount=i.count;items_[i.stableId]=i;return true;}SalvageFailure SalvageRuntime::begin(SalvageTransaction t){if(!t.stableId||!t.itemStableId||!t.cargoEndpointId||!t.requestedCount||!items_.contains(t.itemStableId))return SalvageFailure::Invalid;if(transactions_.contains(t.stableId)||processed_.contains(t.stableId))return SalvageFailure::DuplicateTransaction;if(items_[t.itemStableId].remainingCount==0)return SalvageFailure::AlreadySalvaged;transactions_[t.stableId]=t;return SalvageFailure::None;}
SalvageResult SalvageRuntime::progress(std::uint64_t id,CargoCapacitySnapshot&c){if(auto p=processed_.find(id);p!=processed_.end()){auto r=p->second;r.duplicate=true;return r;}SalvageResult o;auto ti=transactions_.find(id);if(ti==transactions_.end()){o.failure=SalvageFailure::Invalid;return o;}auto&t=ti->second;if(c.endpointStableId!=t.cargoEndpointId){o.failure=SalvageFailure::Invalid;return o;}if(c.revision!=t.expectedCargoRevision){o.failure=SalvageFailure::RevisionConflict;return o;}if(!c.transferLinked){o.failure=SalvageFailure::NoTransferLink;t.state=SalvageTxnState::Paused;return o;}auto&i=items_[t.itemStableId];const auto want=std::min(t.requestedCount-t.movedCount,i.remainingCount);const auto freeMass=c.massCapacity>c.massUsed?c.massCapacity-c.massUsed:0;const auto freeVol=c.volumeCapacity>c.volumeUsed?c.volumeCapacity-c.volumeUsed:0;const auto byMass=i.unitMass?freeMass/i.unitMass:0;const auto byVol=i.unitVolume?freeVol/i.unitVolume:0;const auto move=std::min({want,byMass,byVol});if(!move){o.failure=byMass==0?SalvageFailure::TooHeavy:SalvageFailure::NoCargoVolume;t.state=SalvageTxnState::Paused;return o;}i.remainingCount-=move;t.movedCount=elysium::safe::saturatingAdd(t.movedCount,move);c.massUsed=elysium::safe::saturatingAdd(c.massUsed,elysium::safe::saturatingMultiply(move,i.unitMass));c.volumeUsed=elysium::safe::saturatingAdd(c.volumeUsed,elysium::safe::saturatingMultiply(move,i.unitVolume));c.revision=elysium::safe::saturatingIncrement(c.revision);t.expectedCargoRevision=c.revision;t.revision=elysium::safe::saturatingIncrement(t.revision);t.state=(t.movedCount>=t.requestedCount||i.remainingCount==0)?SalvageTxnState::Completed:SalvageTxnState::InProgress;o.committed=true;o.movedCount=move;o.remainingCount=i.remainingCount;if(t.state==SalvageTxnState::Completed)processed_[id]=o;return o;}
bool SalvageRuntime::cancel(std::uint64_t id){auto i=transactions_.find(id);if(i==transactions_.end()||i->second.state==SalvageTxnState::Completed)return false;i->second.state=SalvageTxnState::Cancelled;i->second.revision=elysium::safe::saturatingIncrement(i->second.revision);return true;}const SalvageItem*SalvageRuntime::findItem(std::uint64_t id)const{auto i=items_.find(id);return i==items_.end()?nullptr:&i->second;}SalvageSnapshot SalvageRuntime::snapshot()const{SalvageSnapshot s;for(auto&[_,i]:items_)s.items.push_back(i);for(auto&[_,t]:transactions_)s.transactions.push_back(t);return s;}bool SalvageRuntime::restore(const SalvageSnapshot&s){SalvageRuntime r;for(auto i:s.items){if(!i.stableId||r.items_.contains(i.stableId))return false;r.items_[i.stableId]=i;}for(auto t:s.transactions){if(!t.stableId||r.transactions_.contains(t.stableId)||!r.items_.contains(t.itemStableId))return false;r.transactions_[t.stableId]=t;}*this=std::move(r);return true;}
} // namespace elysium::derelict
